// QueryReviewedJobs queries the reviewed_jobs edge of a User.
func (c *UserClient) QueryReviewedJobs(_m *User) *JobPostingQuery {
	query := (&JobPostingClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(user.Table, user.FieldID, id),
			sqlgraph.To(jobposting.Table, jobposting.FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, user.ReviewedJobsTable, user.ReviewedJobsColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

